--!strict
local Players=game:GetService("Players");local Config=require(game:GetService("ReplicatedStorage").Modules.PuzzleConfig);local remotes=require(script.Parent.RemoteService).Ensure();local Service={};local states:{[string]:{[Player]:any}}={}
local function player(hit:BasePart):Player?local n:Instance?=hit;while n and n~=workspace do if n:IsA("Model")and n:FindFirstChildOfClass("Humanoid")then return Players:GetPlayerFromCharacter(n)end;n=n.Parent end;return nil end
function Service.Bind(matchId:string,map:Folder)local puzzles=map:FindFirstChild("Puzzles");if not puzzles then return end;states[matchId]={};local door=puzzles:FindFirstChild("ColorDoor")::BasePart?;for _,button in puzzles:GetChildren()do if button:IsA("BasePart")and button:GetAttribute("PuzzleId")=="ColorDoor"and button:GetAttribute("Step")then button.Touched:Connect(function(hit)local p=player(hit);if not p then return end;local all=states[matchId];local s=all[p]or{CurrentStep=1,Completed=false,StartedAt=os.clock(),ResetCount=0,HintLevel=0};all[p]=s;if s.Completed then return end;local expected=Config.WorkshopColorSequence[s.CurrentStep];if button:GetAttribute("Step")==expected then s.CurrentStep+=1;if s.CurrentStep>#Config.WorkshopColorSequence then s.Completed=true;if door then door.CanCollide=false;door.Transparency=.7 end;remotes.PuzzleMessage:FireClient(p,"顏色順序正確！")end else s.CurrentStep=1;s.ResetCount+=1;remotes.PuzzleMessage:FireClient(p,"順序錯誤，重新開始")end end)end end;task.delay(Config.HintTime,function()if states[matchId]then for p,s in states[matchId]do if not s.Completed then s.HintLevel=1;remotes.PuzzleMessage:FireClient(p,"提示：觀察顏色順序")end end end end);task.delay(Config.AutoCompleteTime,function()if states[matchId]and door then door.CanCollide=false;door.Transparency=.7 end end)end
function Service.Clear(matchId:string)states[matchId]=nil end
return Service
